insert into course (course_id, dept_id, title, credits, sem_no, course_type, coordinator_id, description, skills, careers, next) values
  ('CS101', 'CE', 'Programming Fundamentals', 4, 1, 'Mandatory', 'F02', 'Imperative programming, control flow, functions, recursion and file I/O in C.', ARRAY['C','Problem Solving','Recursion']::text[], ARRAY[]::text[], ARRAY[]::text[]),
  ('MA101', 'MA', 'Engineering Mathematics I', 4, 1, 'Mandatory', 'F05', 'Calculus of one and several variables, sequences, series, matrices.', ARRAY['Calculus','Linear Algebra']::text[], ARRAY[]::text[], ARRAY[]::text[]),
