  ('CS301', 'CE', 'Database Management Systems', 4, 3, 'Mandatory', 'F04', 'Relational model, SQL, normalisation, indexing, transactions.', ARRAY['SQL','Data Modelling','Transactions','Databases']::text[], ARRAY[]::text[], ARRAY[]::text[]),
