insert into lesson_plan (course_id, objectives, modules) values
  ('CS401', ARRAY['Model interface systems as composable, versioned components','Encode visual decisions as tokens and enforce them programmatically','Evaluate accessibility and performance trade-offs in system design']::text[], '[{"n":1,"title":"Foundations","topics":[["Systems thinking for interfaces","22 Jul"],["Design tokens & theming","25 Jul"],["Component anatomy","29 Jul"],["Documentation as contract","01 Aug"]]},{"n":2,"title":"Architecture","topics":[["Composition patterns","05 Aug"],["State ownership & data flow","08 Aug"],["Versioning & deprecation","12 Aug"],["Cross-platform parity","19 Aug"]]},{"n":3,"title":"Design Systems in Practice","topics":[["Accessibility contracts","22 Aug"],["Motion & interaction grammar","26 Aug"],["Governance and adoption metrics","02 Sep"],["Systemic testing strategies","09 Sep"]]},{"n":4,"title":"Advanced Systems","topics":[["Performance budgets","16 Sep"],["Multi-brand architecture","23 Sep"],["System migration case study","30 Sep"],["Capstone review","07 Oct"]]}]'::jsonb),
  ('CS302', ARRAY['Reason about concurrency and scheduling trade-offs','Explain virtual memory and file system implementations']::text[], '[{"n":1,"title":"Processes & Threads","topics":[["OS structure & system calls","21 Jul"],["Process lifecycle","23 Jul"],["Threads & context switching","28 Jul"]]},{"n":2,"title":"Scheduling","topics":[["CPU scheduling algorithms","04 Aug"],["Real-time scheduling","06 Aug"],["Multiprocessor scheduling","11 Aug"]]},{"n":3,"title":"Concurrency","topics":[["Critical sections & locks","18 Aug"],["Semaphores & monitors","20 Aug"],["Deadlock detection","25 Aug"],["Classic synchronisation problems","27 Aug"]]},{"n":4,"title":"Memory & Storage","topics":[["Paging & segmentation","01 Sep"],["Virtual memory","03 Sep"],["File system implementation","08 Sep"],["I/O subsystems","15 Sep"]]}]'::jsonb),
  ('CS305', ARRAY['Select and justify algorithmic strategies','Prove correctness and derive complexity bounds']::text[], '[{"n":1,"title":"Analysis Toolkit","topics":[["Asymptotics & recurrences","20 Jul"],["Divide and conquer","22 Jul"],["Master theorem","27 Jul"]]},{"n":2,"title":"Greedy & DP","topics":[["Greedy exchange arguments","03 Aug"],["Dynamic programming","05 Aug"],["DP on trees and graphs","10 Aug"]]},{"n":3,"title":"Graphs & Flows","topics":[["Shortest paths","17 Aug"],["Max-flow / min-cut","19 Aug"],["Bipartite matching","24 Aug"],["Applications of flows","26 Aug"]]},{"n":4,"title":"Intractability","topics":[["NP-completeness","31 Aug"],["Reductions","02 Sep"],["Approximation algorithms","07 Sep"]]}]'::jsonb),
  ('CS309', ARRAY['Trace data through the protocol stack','Analyse congestion and routing behaviour']::text[], '[{"n":1,"title":"Foundations","topics":[["Layering & service models","20 Jul"],["Physical & link layer","23 Jul"]]},{"n":2,"title":"Network Layer","topics":[["IP addressing & subnetting","30 Jul"],["Routing algorithms","06 Aug"],["BGP & inter-domain routing","13 Aug"]]},{"n":3,"title":"Transport Layer","topics":[["TCP mechanics","20 Aug"],["Congestion control","27 Aug"],["QUIC & modern transport","03 Sep"]]},{"n":4,"title":"Applications & Security","topics":[["DNS & HTTP","10 Sep"],["TLS fundamentals","17 Sep"]]}]'::jsonb),
  ('HS401', ARRAY['Apply ethical frameworks to engineering decisions']::text[], '[{"n":1,"title":"Ethical Frameworks","topics":[["Professional codes of conduct","21 Jul"],["Case studies in engineering failure","04 Aug"]]},{"n":2,"title":"Law & IP","topics":[["Contracts & liability","18 Aug"],["Patents, copyright, licensing","01 Sep"],["Data protection law","15 Sep"]]}]'::jsonb),
  ('CS403', ARRAY['Deliver a working software artefact as a team']::text[], '[{"n":1,"title":"Delivery","topics":[["Problem statement & scope review","24 Jul"],["Mid-review demo","28 Aug"],["Final demo & report","02 Oct"]]}]'::jsonb);
